initial = "idle",
states = {
idle = {
update = function(a, dt) a:wander(20) end,
transitions = {
{ to = "chase", when = function(a) return a:nearestPlayer(46) ~= nil end },
},
},
chase = {
enter = function(a) a:play("run") end,
update = function(a) a:pursue(a.target) end,
